import React from 'react';

const AboutUs = () => {
  return (
    <div>
      <h1>ABOUT MMD ANAALYTICS INDIA PRIVATE LIMITED</h1>
      <p>
        Here is where you type all the real text about your company's history, 
        mission, and vision. You can add as many paragraphs, images, or 
        sections as you want right here!
      </p>

      <h2>Our Core Values</h2>
      <ul>
        <li>Integrity in financial reporting</li>
        <li>Excellence in coal transport</li>
        <li>Customer-first broking</li>
      </ul>
    </div>
  );
};

export default AboutUs;
